import sys; sys.path.insert(0, sys.argv[1]); from batch_lib import write_batch
P=[
('weirbeck_mill','Weirbeck Mill','site',27,61,['ostwick'],"A timber mill on the beck below the village, where Ostwick's corn is weighed in and its flour weighed out. The wheel has turned for three generations of one family.",
 [('wheelhouse','The Wheelhouse','The great wheel, the stones and a floor white to the rafters.'),('millpool','The Mill Pool','Deep, brown and slow, and full of what the weir stops.')],['ostwick'],
 ('gerd','Gerd Sack','Miller of Weirbeck','a floury man with one shoulder higher than the other',"The miller looks at your hands before your face. “You can lift,” he says. “Good. I'm Gerd. Mind the stones.”","Gerd tells you which farmers bring damp corn and hope he will not notice.","“A mill takes a sixteenth,” Gerd says. “Anyone who says I take more can turn the wheel himself.”",'wheelhouse','millpool'),
 ('carry_sacks','Carry sacks to the stones','Up the ladder with a sack on your back, and down again for the next.','wheelhouse',7,16,2,'skill_husbandry',None)),
('netherwick','Netherwick','village',37,64,['ostwick'],"A dozen cottages on the low ground east of Ostwick, where the fields flood in a wet spring and the hay is the best on the demesne.",
 [('haymeads','The Haymeads','Long wet meadows, mown twice a year.'),('row','The Row','One street of cottages, each with its hayrick.')],['ostwick'],
 ('alder','Alder Finch','Hayward of Netherwick','a lean man walking the hedge with a billhook, counting gaps',"“Mind the gate,” says the man with the billhook, before anything else. Then, when you have minded it: “Alder Finch. Hayward. That means the hedges are my fault.”","Alder can tell you whose cow got into whose corn, in what year, and what it cost.","“Hedges are law you can see,” Alder says.",'haymeads','row'),
 ('mow_meadow','Mow the haymead','Scythe low, step, scythe low. Keep the line with the man beside you.','haymeads',6,12,3,'skill_husbandry',None)),
('tithe_barn','The Tithe Barn','site',34,55,['ostwick','tennfels'],"A great aisled barn on the Ostwick road where the Duke's tenth is counted, stored and carted up to the castle.",
 [('threshing_floor','The Threshing Floor','Flails in winter, sparrows all year.'),('tally_room','The Tally Room','A table, a tally-stick rack and a locked chest.')],['ostwick'],
 ('wilmar','Wilmar Tally','Clerk of the Tithe','a neat young man with ink on his cuffs and a notched stick behind his ear',"“Name and holding,” says the clerk, without looking up. When you have neither, he looks up. “Wilmar. I count what is owed.”","Wilmar explains the split tally: one half for the tenant, one for the Duke, and no arguing with wood.","“Everyone thinks the tenth is the sheaf I take,” Wilmar says. “It is the nine I leave.”",'tally_room','tally_room'),
 ('thresh_corn','Thresh with the flail','Swing, turn the sheaf, swing. The rhythm matters more than the arm.','threshing_floor',8,16,2,'skill_husbandry',None)),
('crow_stone','The Crow Stone','site',29,52,['ostwick'],"A leaning grey stone on the common boundary, older than the village. The shepherds meet here at noon and will not say why it is unlucky to sit with your back to it.",
 [('stone','The Stone','Taller than a man, and warm on the south side.'),('fold','The Lambing Fold','Hurdles and a turf hut on the lee of the hill.')],['ostwick'],
 ('nell','Old Nell Crook','Shepherd of the Common','an old woman knitting as she walks, with two dogs that watch you instead of the sheep',"The old woman finishes her row before she speaks. “You'll be the new one. Nell. The dogs are Bit and Bother. Don't feed Bother.”","Nell knows every ewe on the common by its face and most by its mother's.","“Sit facing the stone,” Nell says. “Never mind why. Your grandmother would have known.”",'stone','fold'),
 ('count_ewes','Count the ewes at noon','Every head on the common, twice, and the same number both times.','stone',11,14,1,'skill_beastcraft',10)),
('dunmere','Dunmere','village',38,52,['ostwick','tennfels'],"A village round a brown pond on the castle road, known for geese, goose-down and the noise of both.",
 [('pond','The Mere','A wide brown pond, white with geese.'),('green','The Goose Green','Trodden bare, and loud.')],['tithe_barn','ostwick'],
 ('lise','Lise Marsh','Goose-Girl of Dunmere','a young woman with a long switch and a flock that goes where she looks',"The geese reach you before she does. “They don't bite,” says the girl with the switch. “Well. That one bites. I'm Lise.”","Lise drives forty geese to the castle kitchens every week and comes home with thirty-nine fewer.","“Geese know who is afraid of them,” Lise says. “So do I.”",'pond','green'),
 ('pluck_down','Pluck down','A goose under one arm, a sack under the other, and patience.','green',8,15,2,'skill_beastcraft',None)),
('three_ash_ford','Three Ash Ford','site',41,58,['ostwick'],"A stony ford under three ash trees, where the Aschau road crosses the beck. A plank bridge serves in summer; in spring there is only the ford-keeper's rope.",
 [('ford','The Ford','Knee-deep in summer, and no place for a cart in spring.'),('hut',"The Ford-Keeper's Hut",'Turf, a fire, and a rope coiled by the door.')],['netherwick','dunmere'],
 ('hob','Hob Wade','Keeper of the Ford','a broad man standing in the water as if it were a road',"“Wait,” says the man in the water, and you wait while he reads the beck. “Now.” On the far side: “Hob. I say when.”","Hob has pulled eleven carts, two friars and a bull out of the beck, and remembers the bull best.","“Water tells you everything,” Hob says, “just before it is too late.”",'ford','hut'),
 ('read_water','Read the water','Watch the stones, the colour and the speed, and say whether a cart may cross.','ford',6,18,1,'skill_wayfaring',10)),
('hollin_cross','Hollin Cross','site',35,70,['ostwick','aschau'],"A crossroads under holly trees with a wayside hearth of Ilvara, where travellers leave a stick for the fire and take a coal for their own.",
 [('hearth','The Wayside Hearth','A stone bowl of embers under a slate roof.'),('crossroads','The Four Ways','Four tracks, a holly hedge and a post with no sign.')],['netherwick','ostwick'],
 ('berta','Berta Ash','Hearth-Keeper of the Cross','a woman with soot to the elbows, feeding a fire one stick at a time',"She takes your stick, looks it over and lays it on. “Dry. Good. I'm Berta. The fire is older than the road.”","Berta walks to the Ostwick shrine each week and carries a coal back in a clay pot.","“People think a hearth is kept by wood,” Berta says. “It is kept by coming back.”",'hearth','hearth'),
 ('carry_coal','Carry a coal for a traveller','Bank it in ash in a clay pot, and bring it a mile down the road alive.','hearth',6,20,1,'skill_devotion',None)),
('sallowfield','Sallowfield','village',26,70,['ostwick','pomerell'],"A hamlet at the edge of the abbey's orchards, whose people pick for the brothers in autumn and prune for them in winter.",
 [('orchard_edge','The Orchard Edge','The last numbered trees, and the first unnumbered ones.'),('cots',"The Pickers' Cots",'Low cottages with ladders along every wall.')],['weirbeck_mill','hollin_cross'],
 ('tom','Tom Russet','Picker of Sallowfield','a long-armed man who looks at trees the way other men look at horses',"“That one will crop heavy,” says the long-armed man, nodding at a tree. Then at you: “Tom. You pick?”","Tom knows the abbey's trees by their numbers and disagrees with the brothers about four of them.","“A ladder is only as good as its foot,” Tom says.",'orchard_edge','cots'),
 ('prune_trees','Prune the outer trees','Cut to the bud that faces out. Leave the tree room to breathe.','orchard_edge',8,15,2,'skill_husbandry',None)),
('hanging_oak','The Hanging Oak','site',36,46,['tennfels','grauwald'],"A dead oak at the forest road's first turning, where the Duke's justice hangs outlaws in sight of the trees they came from.",
 [('oak','The Oak','Bare, grey, and never quite empty.'),('pit','The Lime Pit','Where what is cut down is put.')],['tithe_barn','dunmere'],
 ('kunz','Kunz Hemp',"The Duke's Hangman","a quiet man mending a rope with a sailmaker's care","He does not offer a hand. “Folk would rather not,” he says. “Kunz. I am paid by the Duke and thanked by nobody.”","Kunz says a good knot is a kindness, and that he has never yet been asked what he thinks of a sentence.","“They cross the road to miss me,” Kunz says. “Then they send for me when a tooth wants pulling.”",'oak','pit'),
 ('splice_rope','Splice rope','Unlay the strands, marry them, and tuck each one three times.','oak',8,16,1,'skill_seamanship',None)),
('undercrag','Undercrag','village',46,49,['tennfels'],"The servants' village under the basalt crag: laundresses, scullions and grooms, and wash-lines strung from the castle rock itself.",
 [('wash_stones','The Wash-Stones','Flat rocks in the Tenn, worn hollow by knees.'),('lines','The Lines','A hundred shirts drying under a castle.')],['dunmere','tennfels'],
 ('anke','Anke Dorn','Laundress to the Castle','a red-armed woman who can tell a knight by his shirts',"“Whose are you?” she asks, and when you are nobody's: “Then you can carry. Anke. Those are the Duke's. Don't drop them.”","Anke knows which knights are in debt, which are in love and which are ill, all from the linen.","“There are no secrets in a castle,” Anke says. “There is only washing.”",'wash_stones','lines'),
 ('beat_linen','Beat the linen','Soap, stone and paddle, until the water runs clear.','wash_stones',6,13,2,'skill_stewardship',None)),
('broken_lance','The Broken Lance','site',50,50,['tennfels'],"An inn on the road below the tiltyard, kept by an old man-at-arms, where squires drink before a tourney and knights after one.",
 [('long_room','The Long Room','Benches, a fire and a splintered lance over the mantel.'),('yard','The Stable Yard','Somebody is always walking a hot horse.')],['undercrag','tennfels'],
 ('dirk','Dirk Hale','Host of the Broken Lance',"a grey man with a sergeant's voice and a limp he does not discuss","“Sit,” says the host, in a voice that has moved pikemen. You sit. “Dirk. Served the Duke twenty years. Now I serve his squires, which is worse.”","Dirk will tell you who unhorsed whom at any tourney for thirty years, and why it was the horse's fault.","“The lance over the fire is mine,” Dirk says. “The man who broke it paid for the inn.”",'long_room','long_room'),
 ('walk_horses','Walk the hot horses','Round the yard at a slow walk until the steam is off them.','yard',10,19,1,'skill_beastcraft',None)),
('falkenau','Falkenau','village',54,42,['tennfels'],"A village on the windy side of the crag where the ducal falconers live, every roof with its block and every child with a glove.",
 [('weathering','The Weathering Ground','Blocks and bow-perches in rows, and hooded birds in the sun.'),('lofts',"The Lure-Makers' Lofts",'Feathers, leather and bells.')],['broken_lance','tennfels'],
 ('jutta','Jutta Lark','Lure-Maker of Falkenau','a small woman stitching a leather lure, with a hawk asleep on the chair-back',"“Don't look her in the eye,” says the woman with the needle, meaning the hawk. “Jutta. She is Thistle. She is in a mood.”","Jutta makes lures for the ducal mews and can tell you which of the Duke's birds will never be any good.","“A hawk does not love you,” Jutta says. “She agrees with you. For now.”",'weathering','lofts'),
 ('swing_lure','Swing the lure','A clean circle, a clean throw, and take it away before she binds to it.','weathering',7,12,1,'skill_beastcraft',10)),
('black_quarry','The Black Quarry','site',51,40,['tennfels'],"The basalt quarry that built the keep, still worked for kerbs and millstones by a few families who say the Duke owes them for a castle.",
 [('face','The Face','Black columns, split along lines the stone chose.'),('sheds','The Dressing Sheds','Chips to the ankle and the ring of mauls.')],['falkenau','hanging_oak'],
 ('bruno','Bruno Slate','Quarryman','a man the colour of his stone, with a maul over his shoulder',"He raps the rock and listens. “Sound,” he says, to the rock, and then to you: “Bruno. Stand there. Not there.”","Bruno's grandfather cut the keep's gate-arch and was paid, the family says, in promises.","“Stone splits where it wants,” Bruno says. “The craft is in wanting the same.”",'face','sheds'),
 ('dress_stone','Dress a kerbstone','Pitch, punch and point, until the face is true.','sheds',7,16,3,'skill_building',None)),
('burners_ride',"The Burners' Ride",'site',33,40,['grauwald'],"A wide track where the charcoal carts come out of the Grauwald, black-rutted and lined with stacked cordwood waiting for the kilns.",
 [('stacks','The Cordwood Stacks',"Beech in fathoms, each stack with its burner's mark."),('halt',"The Carters' Halt",'A trough, a fire-ring and a great deal of soot.')],['hanging_oak','grauwald'],
 ('mats','Mats Cole','Charcoal Carter','a man black to the eyes, leading an ox that is black to the knees',"White teeth in a black face. “Don't shake hands,” he says. “Mats. You'll want to stand upwind.”","Mats carries charcoal to the Silberhalde smelters and news back, and charges for neither.","“The forest burns slow or it burns fast,” Mats says. “We are the slow.”",'stacks','halt'),
 ('stack_cordwood','Stack cordwood','Four feet high, eight feet long, and tight enough that a squirrel cannot pass.','stacks',7,17,2,'skill_woodcraft',None)),
('verderers_lodge',"The Verderer's Lodge",'site',36,36,['grauwald','tennfels'],"A timber lodge inside the forest where the Duke's foresters keep the hunting-rolls, the deer-count and a cellar for poachers.",
 [('hall','The Lodge Hall','Antlers to the roof-tree, each with a year carved under it.'),('paddock','The Deer-Hay','A fenced lawn where the hinds are fed in hard winters.')],['burners_ride','grauwald'],
 ('hilde','Hilde Bracken','Forester of the Grauwald','a woman in green and grey who was standing there some time before you saw her',"“You walk loud,” she says, from much nearer than you thought. “Hilde. The Duke's forester. That was not a complaint. It was a warning.”","Hilde keeps the deer-count in her head and the roll only for the Duke's clerks.","“Poachers I can forgive,” Hilde says. “It is the ones who leave the snare that I hang.”",'paddock','hall'),
 ('walk_bounds','Walk the forest bounds','From marked oak to marked oak, noting every snare and every stump.','paddock',6,15,3,'skill_woodcraft',10)),
('reedmere','Reedmere','wild',22,50,['wisewoman_hut','ostwick'],"A shallow mere between the common and the forest edge, all reed, heron and mist, where thatch is cut in winter and eels are taken in summer.",
 [('reedbeds','The Reed-Beds','Taller than a man, and louder than you would think.'),('staithe',"The Cutters' Staithe",'A plank landing, two punts and bundles of reed.')],['crow_stone','wisewoman_hut'],
 ('wat','Wat Rush','Reed-Cutter','a man in a punt, cutting without looking, with a pipe that is not lit',"The punt noses in. “Step in the middle,” he says, “or step in the mere.” When you are aboard: “Wat. I thatch half of Ostwick.”","Wat sells thatch to the village and eels to the miller, and will not say what he sells to Mother Brindl.","“Reed grows back,” Wat says. “That is the whole of what I know, and it has fed me fifty years.”",'reedbeds','staithe'),
 ('cut_reed','Cut reed for thatch','Sickle low to the water, bundle, tie and stack it in the punt.','reedbeds',7,15,2,'skill_husbandry',None)),
('steinwick','Steinwick','village',40,66,['ostwick','aschau'],"A sheep village of dry-stone walls on the rising ground toward Aschau, where everything that is not a wall is a fold.",
 [('shearing_floor','The Shearing Floor','Boards worn smooth by fleeces.'),('walls','The Long Walls',"Miles of stone, each field's corner with its own builder's trick.")],['three_ash_ford','hollin_cross'],
 ('else','Else Fold','Shearer of Steinwick','a woman with forearms like a smith, sharpening shears on her boot',"“Hold that,” she says, and gives you a ewe. When the ewe has made its views known: “Else. You held on. That'll do.”","Else can shear a ewe while it is still deciding whether to object.","“Wool is the only crop that walks to market,” Else says.",'shearing_floor','walls'),
 ('mend_wall','Mend a dry-stone wall','Two over one, one over two, and a through-stone every yard.','walls',7,16,2,'skill_building',None)),
('vintners_halt',"The Vintners' Halt",'site',43,70,['aschau'],"A carters' stop below the vine slopes, with a cooper's shed, a weighbridge and a pump that every carter swears is haunted.",
 [('cooperage','The Cooperage','Staves, hoops and the smell of scorched oak.'),('weighbridge','The Weighbridge','A stone platform and an argument.')],['steinwick','aschau'],
 ('henk','Henk Stave','Cooper','a cheerful man rolling a cask with one foot while he talks',"The cask rolls up to your feet and stops. “Good, you can catch,” says the cooper. “Henk. That one leaks. Tell me where.”","Henk makes the casks for Aschau's wine and says the wine is only as honest as the wood.","“A cask is a hundred mistakes you did not make,” Henk says.",'cooperage','cooperage'),
 ('raise_cask','Raise a cask','Staves in the hoop, fire inside, and bend them home before they cool.','cooperage',8,16,3,'skill_woodwork',10)),
('pomerell_grange','Pomerell Grange','site',30,77,['pomerell'],"The abbey's outlying farm on the Ostwick side of the hills: a walled yard, a dovecote and the brothers' plough-oxen.",
 [('yard','The Grange Yard','Barns on three sides and a midden on the fourth.'),('dovecote','The Dovecote','Round, white-streaked, and never silent.')],['sallowfield','pomerell'],
 ('otmar','Brother Otmar','Granger of Pomerell','a monk with his sleeves tied back, talking to an ox as to a novice',"“He is called Patience,” says the monk, of the ox. “He is not. I am Brother Otmar, and I am learning it from him.”","Brother Otmar keeps the grange accounts in the same book as the apple-trees, a page to each ox.","“The abbot prays for rain,” Otmar says. “I mend the roof.”",'yard','dovecote'),
 ('yoke_oxen','Yoke the oxen','Bow under the neck, pin through the bow, and a word before you ask them to pull.','yard',6,10,1,'skill_beastcraft',None)),
('beacon_knoll','Beacon Knoll','site',44,54,['tennfels'],"A bald hill between Ostwick and the castle with an iron fire-basket on a post, kept ready to call the Duke's levy.",
 [('basket','The Fire-Basket','Pitch-wood under a tarred cloth, and a flint in a box.'),('watch_hut','The Watch-Hut','One room, one window, facing the castle.')],['dunmere','three_ash_ford'],
 ('rolf','Old Rolf','Beacon-Ward','an old soldier asleep sitting up, with one eye that opens before the other',"One eye opens. “I was not asleep,” says the old man. “I was listening. Rolf. I have lit that fire twice, and I would rather not a third time.”","Rolf was a levy spearman and will show you the scar, whether or not you ask.","“A beacon is the Duke saying please,” Rolf says. “Loudly.”",'basket','watch_hut'),
 ('keep_watch','Keep the beacon watch','Eyes on the castle tower, and the flint dry.','basket',18,22,3,'skill_insight',None)),
]
write_batch(sys.argv[2],'eintenn','eintenn-01',P,'First batch of new places in Eintenn, around Ostwick and Burg Tennfels (Phase 1, issue 28).')
